def make_dataclass2(*fields):
    names = []
    defaults = {}
    for f in fields:
        if isinstance(f, tuple):
            names.append(f[0])
            defaults[f[0]] = f[1]
        else:
            names.append(f)

    def decorate(cls):
        params = []
        for n in names:
            params.append(n if n not in defaults else "%s=%r" % (n, defaults[n]))
        body = "\n    ".join("self.%s = %s" % (n, n) for n in names)
        ns = {}
        exec("def __init__(self, " + ", ".join(params) + "):\n    " + body, ns)
        cls.__init__ = ns["__init__"]
        cls.__fields = tuple(names)
        return cls
    return decorate

