class Book:
    def __init__(self, book_id, title, author):
        self.book_id = book_id
        self.title = title
        self.author = author
        self.borrowed = False


class Library:
    def __init__(self):
        self.books = {}
        self.borrow_counts = {}

    def add(self, book):
        self.books[book.book_id] = book
        self.borrow_counts[book.book_id] = 0

    def borrow(self, book_id):
        book = self.books.get(book_id)
        if book is None:
            return "no such book"
        if book.borrowed:
            return "already borrowed"
        book.borrowed = True
        self.borrow_counts[book_id] += 1
        return "ok"

    def give_back(self, book_id):
        book = self.books.get(book_id)
        if book is None or not book.borrowed:
            return "not borrowed"
        book.borrowed = False
        return "ok"

    def available(self):
        return sorted(b.book_id for b in self.books.values() if not b.borrowed)

    def hottest(self):
        ranked = sorted(self.borrow_counts.items(),
                        key=lambda kv: (-kv[1], kv[0]))
        return ranked[0]


