        self.children = children or []


class DepthFirst:
    def __init__(self, root):
        self.stack = [root]

    def __iter__(self):
        return self

    def __next__(self):
        if not self.stack:
            raise StopIteration
        node = self.stack.pop()
        self.stack.extend(reversed(node.children))
        return node.name


class Tree:
    def __init__(self, root):
        self.root = root

    def __iter__(self):
        return DepthFirst(self.root)


