import collections

class BFS:
    def __init__(self, root):
        self.q = collections.deque((root,), 1000)
    def __iter__(self):
        return self
    def __next__(self):
        if not self.q:
            raise StopIteration
        n = self.q.popleft()
        self.q.extend(n.children)
        return n.name

def leaves(self):
    return [n.name for n in DepthFirst(self.root)
            if not n.children]

