def total_procedural(items):
    total = 0.0
    for o in items:
        if o["paid"]:
            total += o["price"] * o["qty"]
    return total


# 2) 面向对象：把订单与规则封装在类里
class Order:
    def __init__(self, price, qty, paid):
        self.price = price
        self.qty = qty
        self.paid = paid

    def amount(self):
        return self.price * self.qty if self.paid else 0.0


