        self.orders = orders

    def total(self):
        return sum(o.amount() for o in self.orders)


# 3) 函数式：过滤 + 映射 + 折叠
def total_functional(items):
    paid = filter(lambda o: o["paid"], items)
    amounts = map(lambda o: o["price"] * o["qty"], paid)
    total = 0.0
    for a in amounts:
        total += a
    return total


