class Memoized:
    """把函数与它的缓存、调用计数绑在一起的可调用对象。"""

    def __init__(self, func):
        self.func = func
        self.cache = {}
        self.calls = 0

    def __call__(self, *args):
        self.calls += 1
        if args not in self.cache:
            self.cache[args] = self.func(*args)
        return self.cache[args]


def memoize(func):
    return Memoized(func)


@memoize
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)


@memoize
def add(a, b):
    return a + b


