    return -1, comparisons


def binary_search(data, target):
    lo, hi = 0, len(data) - 1
    comparisons = 0
    while lo <= hi:
        comparisons += 1
        mid = (lo + hi) // 2
        if data[mid] == target:
            return mid, comparisons
        if data[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, comparisons


