class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None


class BST:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if self.root is None:
            self.root = TreeNode(value)
            return
        cur = self.root
        while True:
            if value < cur.value:
                if cur.left is None:
                    cur.left = TreeNode(value)
                    return
                cur = cur.left
            else:
                if cur.right is None:
                    cur.right = TreeNode(value)
                    return
                cur = cur.right

    def inorder(self, node=None, acc=None):
        if acc is None:
            node, acc = self.root, []
        if node is None:
            return acc
        self.inorder(node.left, acc)
        acc.append(node.value)
        self.inorder(node.right, acc)
        return acc


def preorder(node, acc=None):
    if acc is None:
        acc = []
    if node is None:
        return acc
    acc.append(node.value)
    preorder(node.left, acc)
    preorder(node.right, acc)
    return acc


def postorder(node, acc=None):
    if acc is None:
        acc = []
    if node is None:
        return acc
    postorder(node.left, acc)
    postorder(node.right, acc)
    acc.append(node.value)
    return acc


def level_order(root):
    import collections
    q = collections.deque((root,), 100)
    out = []
    while q:
        node = q.popleft()
        out.append(node.value)
        if node.left:
            q.append(node.left)
        if node.right:
            q.append(node.right)
    return out


